<?php require 'config.php';require_login();$title='Sales history';$rows=$pdo->query('SELECT s.*,m.name medicine,m.batch_no FROM sales s JOIN medicines m ON m.id=s.medicine_id ORDER BY s.id DESC LIMIT 200')->fetchAll();$sum=(float)$pdo->query('SELECT COALESCE(SUM(total_amount),0) FROM sales')->fetchColumn();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">TRANSACTIONS</div><h1>Sales history</h1><p class="sub">Review completed sales and transaction values.</p></div><a class="btn" href="sales.php">＋ New sale</a></div>
<div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat"><div class="label">Total transactions</div><div class="num"><?=count($rows)?></div><div class="hint">Latest 200 records</div></div><div class="stat"><div class="label">Lifetime sales value</div><div class="num">₹<?=number_format($sum,2)?></div><div class="hint">All recorded transactions</div></div></div>
<div class="card"><div class="cardhead"><h2>Recent transactions</h2></div><div class="tablewrap"><table><thead><tr><th>Sale ID</th><th>Medicine</th><th>Batch</th><th>Customer</th><th>Qty</th><th>Unit price</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><strong><?=h($r['medicine'])?></strong></td><td><?=h($r['batch_no'])?></td><td><?=h($r['customer_name']?:'Walk-in')?></td><td><?=$r['quantity']?></td><td>₹<?=number_format((float)$r['unit_price'],2)?></td><td><strong>₹<?=number_format((float)$r['total_amount'],2)?></strong></td><td><?=h($r['sold_at'])?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8" class="empty">No sales recorded yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
